Mesh<Point, double> result;

  for (auto e = rt.finite_edges_begin(); e != rt.finite_edges_end(); ++e) {
    if (is_small_edge(rt, *e, threshold)) {
      continue;
    }

    std::vector<Point> face;
    auto const &edge = *e;
    auto cells = rt.incident_cells(edge);
    for (auto h : cells) {
      if (h->vertex(0) != RT::Vertex_handle() && h->vertex(1) != RT::Vertex_handle() &&
          h->vertex(2) != RT::Vertex_handle() && h->vertex(3) != RT::Vertex_handle()) {
        Point p = h->circumcenter();
        face.push_back(p);
      }
    }

    if (face.size() >= 3) {
      result.emplace_back(face, rt.segment(edge).squared_length());
    }
  }

  return result;

